let t = 1;
let vel = 1.0;
let num;
let palette_selected;
let palette_selected2;
let w;
let pn;

function setup() {
	w = max(windowWidth, windowHeight);
	createCanvas(w, w);
	angleMode(DEGREES);
	num = random(100);
	palette_selected = random(palettes);

	pg = createGraphics(width, height);
	pn = w * 1;
	for (let i = 0; i < pn; i++) {
		pg.fill(random(palette_selected))
		pg.noStroke();
		pg.ellipse(randomGaussian(width / 2, width * 0.3), randomGaussian(height / 2, height * 0.3), random(1) < 0.99 ? random(width * 0.001, width * 0.004) : random(width * 0.007, width * 0.01))
	}
}

function windowResized() {
	w = max(windowWidth, windowHeight);
	resizeCanvas(w, w);
	angleMode(DEGREES);
	pn = w * 2;
}

function draw() {
	randomSeed(num);
	background(51);
	image(pg, 0, 0);
	tile();
}

function tile() {
	let count = 5;
	let tileW = w / count;
	for (var j = 0.5; j < count; j++) {
		for (var i = 0.5; i < count; i++) {
			crystal(i * tileW, j * tileW, tileW * 0.8);
		}
	}
	t += vel;
}

function crystal(x, y, r) {
	let crystalW = r * 0.6;

	push();
	translate(x, y);
	rectMode(CENTER);
	let colNum = int(random(2, palette_selected.length));
	col = color(palette_selected[colNum]);
	fill(col)
	stroke(palette_selected[1]);
	strokeWeight(r * 0.006)
	strokeCap(ROUND)

	//てっぺんから時計回りに
	push();
	let cn = (r / 2) * 0.6
	let cn2 = crystalW * 0.1;
	let ca = createVector(random(-cn2, cn2), -r / 2 + random(-cn2, cn2));
	let cb = createVector(crystalW / 2 + random(-cn2, cn2), -cn + random(-cn2, cn2));
	let cc = createVector(crystalW / 2 + random(-cn2, cn2), cn + random(-cn2, cn2));
	let cd = createVector(0 + random(-cn2, cn2), r / 2 + random(-cn2, cn2));
	let ce = createVector(-crystalW / 2 + random(-cn2, cn2), cn + random(-cn2, cn2));
	let cf = createVector(-crystalW / 2 + random(-cn2, cn2), -cn + random(-cn2, cn2));
	beginShape();
	vertex(ca.x, ca.y);
	vertex(cb.x, cb.y);
	vertex(cc.x, cc.y);
	vertex(cd.x, cd.y);
	vertex(ce.x, ce.y);
	vertex(cf.x, cf.y);
	endShape(CLOSE);
	pop();

	drawingContext.clip();
	push();
	for (let i = 0; i < 100; i++) {
		inclusions(randomGaussian(0, crystalW * 0.3), randomGaussian(0, r * 0.3), random(r * 0.4))
	}

	push();
	fill(random(palette_selected))
	blendMode(OVERLAY)
	col.setAlpha(180)
	fill(col)
	rect(0, 0, crystalW * 1.5, r * 1.5)
	pop();

	//bubble
	noStroke();
	for (let i = 0; i < 100; i++) {
		ellipse(randomGaussian(0, crystalW * 0.3), randomGaussian(r * 0.6, r * 0.3), random(crystalW * 0.1))
	}
	pop();
	//lines----------------
	push();
	let rw = (crystalW * 0.4) / 2;
	let rh = (r * 0.6) / 2;
	line(cb.x, cb.y, rw, -rh);
	line(cc.x, cc.y, rw, rh);
	line(ce.x, ce.y, -rw, rh);
	line(cf.x, cf.y, -rw, -rh);
	line(cd.x, cd.y, rw, rh);
	line(cd.x, cd.y, -rw, rh);
	line(ca.x, ca.y, rw, -rh);
	line(ca.x, ca.y, -rw, -rh);
	noFill();
	rect(0, 0, rw * 2, rh * 2)
	pop();
	pop();
}

function inclusions(x, y, r) {
	//diamond shape
	palette_selected2 = random(palettes);
	let hr = r / 2;
	push();
	let mo = [ADD, DARKEST, LIGHTEST, MULTIPLY, SCREEN, OVERLAY, DIFFERENCE]
	blendMode(random(mo));
	translate(x, y);
	rotate(random(-10, 10))
	push();
	let rw = random(-1, 1);
	let rr = random(r);
	translate(rw * (rr * (sin(random(10) + t))), rw * (rr * (cos(random(10) + t))));

	let centrW = random(-hr * 0.5, hr * 0.5)
	let centrH = random(-hr * 0.5, hr * 0.5)
	let colNum2 = int(random(1, palette_selected2.length));
	col2 = color(palette_selected2[colNum2]);

	stroke(col2);
	strokeWeight(r * 0.01);
	col2.setAlpha(random(100, 255));
	fill(col2);
	quad(0, -hr, hr, 0, 0, hr, -hr, 0);

	line(0, -hr, centrW, centrH);
	line(hr, 0, centrW, centrH);
	line(0, hr, centrW, centrH);
	line(-hr, 0, centrW, centrH);
	pop();
	pop();
}

